/**
 * Product Filtering Utility for Customer Storefront
 * Excludes test script artifacts generated by verification scripts
 * without modifying database records or breaking admin/test workflows.
 */

export const isLegitProduct = (product) => {
  if (!product || !product.name) return false;
  const name = product.name.trim();

  // Exclude test script artifacts
  if (/^Verify/i.test(name)) return false;
  if (/^Order Test/i.test(name)) return false;
  if (/^Single Stock/i.test(name)) return false;
  if (/^Test Product/i.test(name)) return false;
  if (/^Sports Gear/i.test(name)) return false;
  if (/\d{10,}/.test(name)) return false;

  return true;
};

export const filterLegitProducts = (products = []) => {
  if (!Array.isArray(products)) return [];
  return products.filter(isLegitProduct);
};
